//! Items the code generated by `#[derive(XamlType)]` names. Not part of the stable API.

use std::fmt::{Debug, Formatter, Result};
use std::str::FromStr;

pub use crate::{
  ArgInfo, AttachedPropertyInfo, AttachedTarget, ContentInfo, EventInfo, MarkupExtensionInfo, OverrideDefaults, PropertyGroup,
  PropertyGroupInfo, PropertyInfo, PropertyRef, TypeInfo, ValueError, Whitespace, XamlCollection, XamlType, register_type,
};
pub use artic_core::Object;
pub use artic_core::event::Event;
pub use artic_core::property::{
  Affects, AnyProperty, AttachedKey, Inheritance, ParseEnumError, Property, PropertyKey, SharedKey, inherit,
};
pub use artic_core::tree::{NodeId, UiTree};
pub use std::marker::PhantomData;

/// Wraps a property's value type for the check below.
pub struct ValueCheck<T>(pub PhantomData<T>);

impl<T> Debug for ValueCheck<T> {
  fn fmt(&self, formatter: &mut Formatter<'_>) -> Result {
    formatter.write_str("ValueCheck")
  }
}

/// The value type can be written as text.
pub trait ViaFromStr {
  fn value_must_implement_fromstr_or_derive_xamltype(&self) {}
}

impl<T: FromStr> ViaFromStr for ValueCheck<T> {}

/// The value type is itself a XAML type, written as an object element.
pub trait ViaXamlType {
  fn value_must_implement_fromstr_or_derive_xamltype(&self) {}
}

impl<T: XamlType> ViaXamlType for &ValueCheck<T> {}

/// The value is a child element, filled in by the element written inside.
pub trait ViaChild {
  fn value_must_implement_fromstr_or_derive_xamltype(&self) {}
}

impl ViaChild for &&ValueCheck<NodeId> {}

/// Compiles only if `T` is a collection of child elements.
pub const fn assert_collection<T: XamlCollection>() {}

/// Compiles only if `T` is a property group.
pub const fn assert_property_group<T: PropertyGroup>() {}

/// The content a flattened group gives the type that holds it in `field`.
pub const fn group_content(field: &'static str, info: Option<&'static PropertyInfo>) -> Option<ContentInfo> {
  match info {
    Some(info) => Some(ContentInfo::Property(PropertyRef {
      group: Some(field),
      info,
    })),
    None => None,
  }
}

/// The one content candidate that is set, if any.
///
/// # Panics
///
/// At compile time, when more than one is set: a type has at most one content member, counting the
/// groups it flattens.
pub const fn one_content(candidates: &[Option<ContentInfo>]) -> Option<ContentInfo> {
  let mut found = None;
  let mut index = 0;
  while index < candidates.len() {
    if let Some(candidate) = candidates[index] {
      assert!(
        found.is_none(),
        "a type has at most one `#[xaml(content)]` member, counting the groups it flattens"
      );
      found = Some(candidate);
    }
    index += 1;
  }
  found
}

/// A key a field may name its own default beside: a property key, through any number of
/// references. An attached key brings its own default, and two could disagree.
#[diagnostic::on_unimplemented(
  message = "`default` can't go beside an attached key",
  label = "this attached key already gives the field its default",
  note = "remove `default = ...`; the field starts at the attached property's default"
)]
pub trait TakesDefault {}

impl<T> TakesDefault for PropertyKey<T> {}

impl<K: TakesDefault + ?Sized> TakesDefault for &K {}

/// Returns `value`, the default a field names beside `key`, once the compiler has checked that
/// `key` may take one.
pub fn default_beside<K: TakesDefault + ?Sized, T>(key: &K, value: T) -> T {
  let _ = key;
  value
}

#[cfg(test)]
mod tests {
  use super::*;

  #[derive(Debug)]
  struct Gauge;

  impl XamlType for Gauge {
    const TYPE_INFO: &'static TypeInfo = &GAUGE;
  }

  static GAUGE: TypeInfo = TypeInfo {
    name: "Gauge",
    namespace: "https://fixtures.artic.test",
    rust_path: "tests::Gauge",
    new: |_| unreachable!("never created"),
    content: None,
    is_collection: false,
    properties: &[],
    groups: &[],
    events: &[],
    attached_properties: &[],
    markup_extension: None,
    whitespace: Whitespace::Collapse,
  };

  // The check resolves for a FromStr type, a XAML type and a child node. A type that is none of
  // them fails to compile, which the derive's compile-fail tests cover.
  #[test]
  #[allow(
    clippy::needless_borrow,
    reason = "the extra references pick the matching check, as in generated code"
  )]
  fn value_check_accepts_text_object_and_child_values() {
    (&&ValueCheck::<f32>(PhantomData)).value_must_implement_fromstr_or_derive_xamltype();
    (&&ValueCheck::<Gauge>(PhantomData)).value_must_implement_fromstr_or_derive_xamltype();
    (&&ValueCheck::<NodeId>(PhantomData)).value_must_implement_fromstr_or_derive_xamltype();
  }
}
